using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Benchmark.Api;
using Benchmark.Application;
using Benchmark.Domain;
using Benchmark.Infrastructure;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;
var builder = WebApplication.CreateBuilder(args);
var key = builder.Configuration["Jwt:SigningKey"] ?? throw new InvalidOperationException("Jwt:SigningKey is required.");
var issuer = builder.Configuration["Jwt:Issuer"] ?? throw new InvalidOperationException("Jwt:Issuer is required.");
var audience = builder.Configuration["Jwt:Audience"] ?? throw new InvalidOperationException("Jwt:Audience is required.");
var accounts = new Dictionary<string,(string Password,string Role)> { ["alice@example.test"]=("Alice!234","User"),["bob@example.test"]=("Bob!234","User"),["admin@example.test"]=("Admin!234","Admin") };
builder.Services.AddSingleton<IWorkItemRepository, InMemoryWorkItemRepository>();
builder.Services.AddScoped<WorkItemService>();
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(options => { options.TokenValidationParameters = new TokenValidationParameters { ValidateIssuerSigningKey = true, IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)), ValidateIssuer = true, ValidIssuer = issuer, ValidateAudience = true, ValidAudience = audience, ValidateLifetime = true, ClockSkew = TimeSpan.Zero, NameClaimType = "sub", RoleClaimType = ClaimTypes.Role }; });
builder.Services.AddAuthorization();
var app = builder.Build();
app.UseAuthentication();
app.UseAuthorization();
app.MapGet("/health", () => Results.Ok(new { status = "ok" }));
app.MapPost("/api/auth/login", (LoginInput input) => { if (string.IsNullOrWhiteSpace(input.Email) || string.IsNullOrWhiteSpace(input.Password)) return Results.BadRequest(); if (!accounts.TryGetValue(input.Email, out var account) || account.Password != input.Password) return Results.Unauthorized(); var token = new JwtSecurityToken(issuer, audience, [new Claim(JwtRegisteredClaimNames.Sub, input.Email), new Claim(ClaimTypes.Role, account.Role)], DateTime.UtcNow, DateTime.UtcNow.AddMinutes(15), new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)), SecurityAlgorithms.HmacSha256)); return Results.Ok(new LoginResult(new JwtSecurityTokenHandler().WriteToken(token))); });
app.MapGet("/api/work-items", async (WorkItemService service, HttpContext context, string? status) => { var owner = context.User.FindFirst("sub")?.Value ?? throw new UnauthorizedAccessException(); WorkStatus? parsed = null; if (status is not null) { if (!Enum.TryParse<WorkStatus>(status, out var s)) return Results.BadRequest(); parsed = s; } return Results.Ok(await service.ListAsync(owner, parsed)); }).RequireAuthorization();
app.MapPost("/api/work-items", async (WorkItemService service, HttpContext context, CreateInput input) => { var owner = context.User.FindFirst("sub")?.Value ?? throw new UnauthorizedAccessException(); if (!Enum.TryParse<WorkStatus>(input.Status, out var status)) return Results.BadRequest(); try { var item = await service.AddAsync(owner, input.Title, status); return Results.Created($"/api/work-items/{item.Id}", new ItemDto(item.Id, item.Title, item.Status.ToString(), item.Version)); } catch (ArgumentException) { return Results.BadRequest(); } }).RequireAuthorization();
app.MapPut("/api/work-items/{id:guid}", async (WorkItemService service, HttpContext context, Guid id, UpdateInput input) => { var owner = context.User.FindFirst("sub")?.Value ?? throw new UnauthorizedAccessException(); if (!Enum.TryParse<WorkStatus>(input.Status, out var status)) return Results.BadRequest(); try { var item = await service.UpdateAsync(owner, id, input.Title, status, input.ExpectedVersion); return Results.Ok(new ItemDto(item.Id, item.Title, item.Status.ToString(), item.Version)); } catch (ArgumentException) { return Results.BadRequest(); } catch (ItemNotFoundException) { return Results.NotFound(); } catch (VersionConflictException) { return Results.Conflict(); } }).RequireAuthorization();
app.MapDelete("/api/work-items/{id:guid}", async (WorkItemService service, HttpContext context, Guid id, int? expectedVersion) => { var owner = context.User.FindFirst("sub")?.Value ?? throw new UnauthorizedAccessException(); if (expectedVersion is null || expectedVersion < 1) return Results.BadRequest(); try { await service.DeleteAsync(owner, id, expectedVersion.Value); return Results.NoContent(); } catch (ArgumentException) { return Results.BadRequest(); } catch (ItemNotFoundException) { return Results.NotFound(); } catch (VersionConflictException) { return Results.Conflict(); } }).RequireAuthorization();
app.Run();
public partial class Program { }
